// Chapter 8 situations. Sign pixels are unaltered official artwork; coloured
// arrows indicate traffic movement, not a new road sign or an answer.
const CH8_SIGN_ONLY = Object.freeze({6:'E 37',7:'E 55',12:'E 39',13:'A 41,1',17:'A 72',18:'A 74,1',19:'A 75',23:'B 15',25:'E 16,2',29:'A 22',31:'A 23',33:'B 18',34:'B 19',57:'C 51',66:'E 47',74:'E 44',75:'I 13',76:'E 34',92:'E 43',120:'X 19'});
function ch8Art(code,x,y,w,h=w){
  const art=OFFICIAL_SIGN_ART[code];
  if(!art)throw new Error(`Missing official sign artwork: ${code}`);
  return `<image href="${art.src}" x="${x}" y="${y}" width="${w}" height="${h}" preserveAspectRatio="xMidYMid meet" data-official-sign="${esc(code)}"/>`;
}
function ch8Note(text,x=320,y=302){return `${rect(x-145,y-23,290,34,C.panel,6)}${txt(x,y,text,17,C.white,'middle',700)}`;}
function ch8Arrow(x,y,endX,endY,color=C.yellow){
 const angle=Math.atan2(endY-y,endX-x),h=12;
 return `${line(x,y,endX,endY,color,4,'9 7')}${path(`M ${endX} ${endY} L ${endX-h*Math.cos(angle-.55)} ${endY-h*Math.sin(angle-.55)} L ${endX-h*Math.cos(angle+.55)} ${endY-h*Math.sin(angle+.55)} Z`,color,'none',0)}`;
}
function ch8Truck(x,y,color=C.coral,label='LASTBIL'){
 return `${rect(x-58,y-18,84,36,color,4)}${rect(x+28,y-15,30,33,color,5)}${rect(x+40,y-12,13,13,C.dark,2)}${circle(x-40,y+20,7,C.dark)}${circle(x+4,y+20,7,C.dark)}${circle(x+44,y+20,7,C.dark)}${txt(x-14,y+5,label,11,C.dark,'middle',850)}`;
}
function ch8Tractor(x,y){return `${rect(x-16,y-18,31,31,C.coral,3)}${rect(x+15,y-4,25,15,C.coral,2)}${circle(x-8,y+15,15,C.dark,C.white,2)}${circle(x+33,y+16,9,C.dark,C.white,2)}${txt(x+5,y-28,'TRAKTOR',14,C.coral,'middle')}`;}
function ch8Trailer(x,y){return `${car(x,y,0,C.mint,'Dig')}${line(x-27,y,x-43,y,C.muted,4)}${rect(x-100,y-16,56,32,C.muted,4,C.white,2)}${circle(x-83,y+18,6,C.dark)}${circle(x-60,y+18,6,C.dark)}`;}
function ch8Motorway(){return `${rect(145,48,350,270,C.road)}${rect(145,48,18,270,'#334c3c')}${line(170,48,170,318,C.white,3)}${line(275,48,275,318,C.white,2,'22 15')}${line(380,48,380,318,C.white,2,'22 15')}${line(488,48,488,318,C.white,3)}`;}
function ch8Ramp(){return `${ch8Motorway()}${path('M 610 316 L 522 316 Q 449 230 432 137 L 444 137 Q 468 224 610 316 Z',C.road,C.white,2)}${line(490,265,464,220,C.white,2,'9 9')}`;}
function ch8Exit(){return `${ch8Motorway()}${path('M 610 48 L 522 48 Q 449 134 432 227 L 444 227 Q 468 140 610 48 Z',C.road,C.white,2)}${line(490,99,464,144,C.white,2,'9 9')}`;}
function ch8Rail(){let ties='';for(let y=60;y<310;y+=23)ties+=line(407,y,451,y,C.muted,5);return `${roadHorizontal()}${ties}${line(417,53,417,315,C.white,4)}${line(443,53,443,315,C.white,4)}`;}
