// Chapter 6: original situation geometry in the established app palette.
// Road-sign pixels are official source artwork, never reconstructed symbols.
function ch6Art(code,x,y,w,h=w){
 const a=CH6_OFFICIAL_ART[code];if(!a)throw Error(`Missing Chapter 6 official artwork ${code}`);
 return `<image href="${a.src}" x="${x}" y="${y}" width="${w}" height="${h}" preserveAspectRatio="xMidYMid meet" data-official-sign="${esc(code)}"/>`;
}
function ch6Note(text,y=304){return `${rect(25,y-24,590,34,C.panel,6)}${txt(320,y,text,17,C.white,'middle',700)}`;}
function ch6Panel(x,y,w,title,lines){return `${rect(x,y,w,38+lines.length*29,C.panel,8,C.muted,2)}${txt(x+w/2,y+27,title,18,C.yellow,'middle',750)}${lines.map((s,i)=>txt(x+w/2,y+56+i*29,s,18,C.white,'middle')).join('')}`;}
function ch6Van(x,y,color=C.mint,label='Dig'){
 return group(`${rect(-70,-30,140,58,color,7)}${rect(32,-25,30,22,C.dark,3)}${line(24,-29,24,24,C.road2,2)}${circle(-45,31,11,C.dark,C.white,2)}${circle(47,31,11,C.dark,C.white,2)}${txt(-20,7,label,15,C.dark,'middle',850)}`,`translate(${x} ${y})`);
}
function ch6Trailer(x,y,label='TRAILER'){
 return `${line(x+54,y+20,x+77,y+20,C.muted,5)}${rect(x-54,y-24,108,49,C.muted,5,C.white,2)}${circle(x,y+28,9,C.dark,C.white,2)}${txt(x,y+6,label,13,C.dark,'middle',850)}`;
}
function ch6TowCombination(bil,trailer,kind){return `${roadHorizontal()}${ch6Van(407,210)}${ch6Trailer(260,210,kind)}${ch6Panel(66,51,230,'Tilladt totalvægt',[`Påhæng: ${trailer} kg`])}${ch6Panel(344,51,230,'Tilladt totalvægt',[`Bil: ${bil} kg`])}${ch6Note('Begge køretøjers tekniske grænser er opfyldt')}`;}
function ch6BeltSeat(x,y,label,color=C.mint){return `${rect(x-25,y-30,50,62,color,8)}${circle(x,y-15,9,C.dark)}${line(x,y-3,x,y+19,C.dark,11)}${line(x-20,y-12,x+20,y+24,C.white,5)}${txt(x,y+53,label,15,C.white,'middle')}`;}
function ch6Phone(title,lines){return `${rect(140,52,360,270,C.panel,18,C.muted,3)}${rect(158,73,324,223,C.road2,8)}${txt(320,108,title,25,C.white,'middle',800)}${lines.map((s,i)=>txt(320,150+i*36,s,19,C.white,'middle')).join('')}${circle(320,308,6,C.muted)}`;}
function ch6Roundabout(){return `${rect(291,43,58,277,C.road)}${rect(25,151,590,58,C.road)}${circle(320,180,102,C.road,C.white,3)}${circle(320,180,55,'#334c3c',C.muted,3)}`;}
function ch6Flashes(x,y,color=C.yellow){return `${line(x-20,y-12,x-30,y-20,color,4)}${line(x-23,y,x-36,y,color,4)}${line(x-20,y+12,x-30,y+20,color,4)}${line(x+20,y-12,x+30,y-20,color,4)}${line(x+23,y,x+36,y,color,4)}${line(x+20,y+12,x+30,y+20,color,4)}`;}
function ch6Triangle(x,y){return `${path(`M ${x} ${y-20} L ${x-24} ${y+20} L ${x+24} ${y+20} Z`,'none',C.red,7)}${path(`M ${x} ${y-10} L ${x-14} ${y+14} L ${x+14} ${y+14} Z`,'none','#ff9b3f',3)}${line(x-20,y+24,x+20,y+24,C.dark,4)}`;}
