function remainingQuestionDiagram(question) {
 const body=REMAINING_DIAGRAMS[question.diagramId];
 if(!body)throw Error('Missing bound Figma diagram '+question.diagramId);
 const labels={'koerekort':'Kørekort og køreprøve','koeretoejer':'Køretøjer omkring dig','risiko-teknik':'Fart, sele og køreteknik','vej-vejr':'Vej, vejr og udsyn','foereren':'Mennesket bag rattet','grundmanoevrer':'Grundmanøvrer','bil':'Bilen før turen'};
 return '<svg xmlns="http://www.w3.org/2000/svg" lang="da" viewBox="0 0 640 360" role="img" aria-label="'+esc(question.diagramAlt)+'" data-question="'+esc(question.id)+'" data-diagram="'+esc(question.diagramId)+'">'+
 '<title>'+esc(labels[question.chapterId]||'Din situation')+'</title><desc>Skematisk illustration. Opgaveteksten angiver alle afgørende betingelser.</desc>'+
 '<rect width="640" height="360" rx="10" fill="#FEFFED"/><text x="28" y="36" fill="#1F2328" font-family="Arial,sans-serif" font-size="17" font-weight="700">'+esc(labels[question.chapterId]||'Din situation')+'</text>'+
 '<g aria-hidden="true">'+body+'</g><text x="320" y="340" text-anchor="middle" fill="#5F656D" font-family="Arial,sans-serif" font-size="13">Skematisk illustration · Betingelserne står i opgaven.</text></svg>';
}
// END REMAINING FIGMA DIAGRAM DATA

export function questionDiagram(q) {
  const question = q && typeof q === 'object' ? q : {};
  if (Object.hasOwn(REMAINING_DIAGRAMS, question.diagramId)) return remainingQuestionDiagram(question);
  if (/^figma-oe(?:10|3|9|5|4|2|1)-/.test(question.diagramId || '')) throw Error('Missing bound Figma diagram '+question.diagramId);
  const chapter7 = /^figma-oe7-(\d+)$/.exec(question.diagramId || '');
  const chapter6 = /^figma-oe6-(\d+)$/.exec(question.diagramId || '');
  const chapter8 = /^figma-oe8-(\d+)$/.exec(question.diagramId || '');
  const type = (chapter7 || chapter6 || chapter8) ? question.diagramId : TYPE_BY_ID[question.id] || 'neutral-context';
  const uid = `nat-${safeId(question.id)}-${safeId(question.sectionId)}`;
  const label = chapter7 ? 'Kryds · din situation' : chapter6 ? 'Grundregler · din situation' : chapter8 ? 'Vejmanøvrer · din situation' : LABEL_BY_TYPE[type] || 'Situationen vises skematisk';
  const aria = question.diagramAlt || `Støtteillustration til ${question.id || 'spørgsmålet'}: ${question.context || label}. Opgaveteksten angiver alle afgørende betingelser.`;
  const body = chapter7 ? chapter7DiagramBody(Number(chapter7[1]), question, uid) : chapter6 ? chapter6DiagramBody(Number(chapter6[1]), question, uid) : chapter8 ? chapter8DiagramBody(Number(chapter8[1]), question) : diagramBody(type, question, uid);
  return `<svg${chapter7 ? ' lang="da"' : ''} xmlns="http://www.w3.org/2000/svg" viewBox="0 0 640 360" role="img" aria-label="${esc(aria)}" data-question="${esc(question.id || '')}" data-diagram="${esc(type)}">`+
    `<title>${esc(label)}</title><desc>${esc('Skematisk støtteillustration. Opgaveteksten er afgørende.')}</desc>`+
    `<defs><linearGradient id="${uid}-bg" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="${C.bg}"/><stop offset="1" stop-color="#0b1219"/></linearGradient></defs>`+
    `${rect(0,0,640,360,`url(#${uid}-bg)`)}`+
    `${rect(18,14,604,28,'rgba(23,37,50,.94)',7)}${txt(32,33,label,12,C.white,'start',750)}`+
    `<g aria-hidden="true">${body}</g>${legend()}</svg>`;
}
